""" utlity for keeping track of layer names """
def get_name(layer_name: Any, counters: Any) -> object {
    if not (layer_name in counters) {
        counters[layer_name] = 0;
    }
    name = layer_name + "_" + str(counters[layer_name]);
    counters[layer_name] += 1;
    return name;
}

